  "confidence": 0.96,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J12", "U1", "U2", "U3", "U4"],
      "pins": ["J12.A6", "J12.B6", "U1.19", "U1.27", "U2.5", "U3.5", "U4.5"],
      "nets": ["SCK"],
      "observed": "The SCK net contains the USB-C D+ pins (J12 A6/B6) and ESP32-C3 GPIO19/USB_D+ (U1 pin 27) in addition to the thermocouple SPI clock pins and GPIO5.",
      "expected": "SCK should be only the shared SPI clock to U2/U3/U4 pin 5 and U1 GPIO5; USB D+ should be a separate USB data net, as USB D- is, not tied to the SPI clock bus.",
      "evidence": [
        {"source": "netlist", "quote": "(net (code \"32\") (name \"SCK\") (class \"Default\") (node (ref \"J12\") (pin \"A6\") (pinfunction \"D+\") (pintype \"bidirectional\"))"},
        {"source": "netlist", "quote": "(node (ref \"U1\") (pin \"27\") (pinfunction \"GPIO19/USB_D+\") (pintype \"bidirectional\"))"},
        {"source": "spec", "quote": "SPI bus is **shared** across all three chips: `SCK` (pin 5) and `SO` (pin 7, tri-state/MISO) are common nets (`SCK`, `SO`) tied to all three ICs and to the ESP32 (`U1` GPIO5/SCK, GPIO10/SO)."}
      ],
      "impact": "USB D+ is shorted to the SPI clock bus and to GPIO19/GPIO5, which can prevent USB programming/enumeration, corrupt thermocouple SPI reads, and create GPIO contention or damage.",
      "confidence": 0.96
    }
  ],
  "summary": "Anomaly detected: the SPI SCK net is bridged to USB-C D+ and ESP32 GPIO19/USB_D+, contrary to the intended SPI/USB separation. Other traced power, heater, thermocouple, and fan paths match the documented design."
}

